float number(jass::Real value){return std::bit_cast<float>(value.bits());}
jass::Real real(float value){return jass::Real::fromBits(std::bit_cast<std::uint32_t>(value));}
bool siege(PassiveKind kind){return kind>=PassiveKind::FlakCannon && kind<=PassiveKind::Barrage || kind==PassiveKind::PlagueToss || kind==PassiveKind::FrostBreath || kind==PassiveKind::FreezingBreath;}
