Bytes ScriptSession::encodeCombatEffects(const jass::StableHandleMap& encodeHandle) const {
    constexpr size_t budget=32u*1024u*1024u;if(!runtime_.snapshotSafe() || failed_ || !world_ || !setupApplied_ || !contexts_.empty() || experimentalSelectionSync_ || !networkPlayers_.empty() || siegeFires_.size()>4096 || attackLightnings_.size()>4096)throw std::runtime_error("Combat effects snapshot requires a quiescent local session");SnapshotWriter out(budget-64);out.u32(tag("SCFX"));out.u32(1);out.text(world_->resources().mapDigest(),64);out.u64(std::bit_cast<std::uint64_t>(simulationTime_));out.u64(attackLightningTicket_);std::map<std::pair<NativeKind,std::uint32_t>,std::uint32_t> forward,reverse;auto ref=[&](std::uint32_t id,NativeKind kind){if(!id){out.u32(0);return;}if(!encodeHandle || id<handleBase || id-handleBase>=objects_.size() || objects_[id-handleBase].kind!=kind)throw std::runtime_error("Invalid combat effect reference");auto saved=encodeHandle(kind==NativeKind::Unit?"unit":"effect",id);auto [a,inserted]=forward.emplace(std::pair{kind,id},saved);auto [b,unique]=reverse.emplace(std::pair{kind,saved},id);if(!saved || (!inserted && a->second!=saved) || (!unique && b->second!=id))throw std::runtime_error("Invalid combat effect mapping");out.u32(saved);out.u32(objects_[id-handleBase].alive?1:0);};auto value=[&](float v){if(!std::isfinite(v))throw std::runtime_error("Invalid combat effect value");out.u32(std::bit_cast<std::uint32_t>(v));};auto point=[&](WorldPoint p){value(number(p.x));value(number(p.y));};auto time=[&](double v){if(!std::isfinite(v) || v<0)throw std::runtime_error("Invalid combat effect time");out.u64(std::bit_cast<std::uint64_t>(v));};size_t refs=0;out.size(siegeFires_.size());for(auto& [id,f]:siegeFires_){auto& p=f.definition;if(!id || id>spellTicket_ || !f.source || f.owner>=16 || p.kind!=PassiveKind::BurningOil || p.period<=0 || p.evasion<=0 || f.visuals.size()>8192 || f.visuals.size()>262144-refs)throw std::runtime_error("Invalid siege fire");refs+=f.visuals.size();out.u64(id);writePassiveSnapshot(out,p);ref(f.source,NativeKind::Unit);out.u32(f.owner);point(f.point);time(f.elapsed);time(f.nextPulse);out.u32(f.burn?1:0);out.size(f.visuals.size());for(auto effect:f.visuals){if(!effect)throw std::runtime_error("Invalid siege fire visual");ref(effect,NativeKind::Effect);}}out.size(attackLightnings_.size());for(auto& [id,l]:attackLightnings_){if(!id || id>attackLightningTicket_ || !l.definition || l.definition->kind!=PassiveKind::LightningAttack || l.definition->lightningType.size()!=4 || l.definition->secondary<=0 || !l.source || !l.target || unsigned(l.startMovement)>unsigned(PathMovement::Amphibious) || unsigned(l.endMovement)>unsigned(PathMovement::Amphibious))throw std::runtime_error("Invalid attack lightning");out.u64(id);writePassiveSnapshot(out,*l.definition);ref(l.source,NativeKind::Unit);ref(l.target,NativeKind::Unit);out.u64(l.sourceDeath);out.u64(l.targetDeath);point(l.start);point(l.end);value(l.startHeight);value(l.endHeight);value(l.sourceFly);value(l.targetFly);out.u32(unsigned(l.startMovement));out.u32(unsigned(l.endMovement));time(l.due);}return sealSnapshot(out.finish(),budget);
}
void ScriptSession::restoreCombatEffects(std::span<const std::uint8_t> bytes,const jass::StableHandleMap& decodeHandle) {
    constexpr size_t budget=32u*1024u*1024u;if(!runtime_.ready() || failed_ || !world_ || !setupApplied_ || mainAttempted_ || !unitRecoveryIncomplete_ || !unitCoreFinished_ || combatEffectsRestored_ || !siegeFires_.empty() || !attackLightnings_.empty() || runtime_.threadCount() || !runtime_.inspectExecutions().empty() || !contexts_.empty() || experimentalSelectionSync_ || !networkPlayers_.empty() || liveObjects(NativeKind::Event))throw std::runtime_error("Combat effects restore requires rebuilt units and effects before events");Binary in(openSnapshot(bytes,budget));in.expect(tag("SCFX"));if(in.u32()!=1 || snapshotText(in,64)!=world_->resources().mapDigest() || snapshotU64(in)!=std::bit_cast<std::uint64_t>(simulationTime_))throw std::runtime_error("Combat effects map or clock differs");auto last=snapshotU64(in);auto flag=[&]{auto v=in.u32();if(v>1)throw std::runtime_error("Invalid combat effect flag");return v!=0;};std::map<std::pair<NativeKind,std::uint32_t>,std::uint32_t> reverse;auto ref=[&](NativeKind kind){auto saved=in.u32();if(!saved)return 0u;auto live=flag();auto id=decodeHandle?decodeHandle(kind==NativeKind::Unit?"unit":"effect",saved):0;auto& identities=kind==NativeKind::Unit?unitIdentityHandles_:effectIdentityHandles_;auto [it,unique]=reverse.emplace(std::pair{kind,id},saved);if(!id || !identities.contains(saved) || identities.at(saved)!=id || id<handleBase || id-handleBase>=objects_.size() || objects_[id-handleBase].kind!=kind || objects_[id-handleBase].alive!=live || (!unique && it->second!=saved))throw std::runtime_error("Invalid combat effect mapping");return id;};auto value=[&]{auto v=std::bit_cast<float>(in.u32());if(!std::isfinite(v))throw std::runtime_error("Invalid combat effect value");return v;};auto point=[&]{return WorldPoint{real(value()),real(value())};};auto time=[&]{auto v=std::bit_cast<double>(snapshotU64(in));if(!std::isfinite(v) || v<0)throw std::runtime_error("Invalid combat effect time");return v;};std::map<std::uint64_t,SiegeFire> fires;auto count=in.count(4,4096);size_t refs=0;for(unsigned i=0;i<count;++i){auto id=snapshotU64(in);SiegeFire f;f.definition=readPassiveSnapshot(in);f.source=ref(NativeKind::Unit);f.owner=in.u32();f.point=point();f.elapsed=time();f.nextPulse=time();f.burn=flag();auto n=in.count(4,8192);if(!id || id>spellTicket_ || !f.source || f.owner>=16 || f.definition.kind!=PassiveKind::BurningOil || f.definition.period<=0 || f.definition.evasion<=0 || n>262144-refs)throw std::runtime_error("Invalid siege fire");refs+=n;for(unsigned j=0;j<n;++j){auto effect=ref(NativeKind::Effect);if(!effect)throw std::runtime_error("Invalid siege fire visual");f.visuals.push_back(effect);}if(!fires.emplace(id,std::move(f)).second)throw std::runtime_error("Duplicate siege fire");}std::map<std::uint64_t,AttackLightning> lightnings;count=in.count(4,4096);for(unsigned i=0;i<count;++i){auto id=snapshotU64(in);AttackLightning l;l.restoredDefinition=std::make_shared<PassiveInfo>(readPassiveSnapshot(in));l.definition=l.restoredDefinition.get();l.source=ref(NativeKind::Unit);l.target=ref(NativeKind::Unit);l.sourceDeath=snapshotU64(in);l.targetDeath=snapshotU64(in);l.start=point();l.end=point();l.startHeight=value();l.endHeight=value();l.sourceFly=value();l.targetFly=value();auto start=in.u32(),end=in.u32();l.due=time();if(!id || id>last || !l.source || !l.target || l.definition->kind!=PassiveKind::LightningAttack || l.definition->lightningType.size()!=4 || l.definition->secondary<=0 || start>unsigned(PathMovement::Amphibious) || end>unsigned(PathMovement::Amphibious))throw std::runtime_error("Invalid attack lightning");l.startMovement=PathMovement(start);l.endMovement=PathMovement(end);if(!lightnings.emplace(id,std::move(l)).second)throw std::runtime_error("Duplicate attack lightning");}in.finish();siegeFires_.swap(fires);attackLightnings_.swap(lightnings);attackLightningTicket_=last;combatEffectsRestored_=true;
}
void ScriptSession::siegePassiveInfo(PassiveInfo& p){
    auto& data=definitions();auto field=[&](const char* name,float fallback=0){return data.number(p.ability,"AbilityData",std::string(name)+std::to_string(p.level),fallback);};
    if(p.kind==PassiveKind::FlakCannon || p.kind==PassiveKind::Fragmentation){p.splashRadii={p.area,p.amount,p.secondary};p.splashDamage={p.bonus,field("DataD"),field("DataE")};for(auto radius:p.splashRadii)if(radius<0 || radius>100000)throw std::runtime_error("Siege splash radius outside supported range");for(auto damage:p.splashDamage)if(damage<0 || damage>1000000)throw std::runtime_error("Siege splash damage outside supported range");}
    if(p.kind==PassiveKind::LiquidFire){float repair=field("DataD");if(!p.buff || p.amount<0 || p.amount>1000000 || p.secondary<0 || p.secondary>1 || p.bonus<0 || p.bonus>5 || (repair!=0 && repair!=1) || p.duration<=0 || p.duration>86400)throw std::runtime_error("Invalid source Liquid Fire damage, suppression or duration");p.repairAllowed=repair!=0;}
    if(p.kind==PassiveKind::BurningOil){p.period=p.secondary;p.innerDamage=p.bonus;p.evasion=field("DataD");p.magicFactor=field("DataE",1);auto effect=data.field(p.ability,"AbilityData","EfctID"+std::to_string(p.level));if(effect.size()==4)p.effectBuff=ObjectData::code(effect);if(p.amount<0 || p.innerDamage<0 || p.area<=0 || p.area>100000 || p.duration<=0 || p.duration>86400 || p.heroDuration<0 || p.heroDuration>p.duration || p.period<=0 || p.evasion<=0 || p.duration/std::min(p.period,p.evasion)>262144 || p.magicFactor<0)throw std::runtime_error("Invalid source Burning Oil schedule");}
    if(p.kind==PassiveKind::Barrage){p.period=field("Cool");if(p.area<=0 || p.area>100000 || p.amount<0 || p.amount>1000000 || p.secondary<0 || p.secondary>100000000 || p.bonus<1 || p.bonus>64 || p.bonus!=std::floor(p.bonus) || p.period<=0 || p.period>86400)throw std::runtime_error("Invalid source Barrage target budget or cooldown");p.maxTargets=unsigned(p.bonus);}
    if(p.kind==PassiveKind::BurningOil || p.kind==PassiveKind::Barrage){p.attackMissile=data.field(p.ability,"Profile","Missileart");if(auto comma=p.attackMissile.find(',');comma!=std::string::npos)p.attackMissile.resize(comma);p.missileSpeed=data.number(p.ability,"Profile","Missilespeed");p.missileArc=data.number(p.ability,"Profile","Missilearc");p.missileHoming=data.number(p.ability,"Profile","MissileHoming",1)!=0;if(p.attackMissile.empty() || p.attackMissile=="_" || p.missileSpeed<=0 || p.missileSpeed>1000000 || p.missileArc<0 || p.missileArc>10)throw std::runtime_error("Invalid source siege missile");p.visualModels.push_back(p.attackMissile);}
    if(p.effectBuff){auto art=data.field(p.effectBuff,"Profile","Effectart");if(!art.empty() && art!="_")p.visualModels.push_back(art);}
}
void ScriptSession::prepareSiegeAttack(const UnitState& unit,CombatProjectile& projectile){
    if(unit.illusion || projectile.definition.kind=="normal")return;for(auto [ability,level]:passiveAbilities(unit)){auto& p=passiveInfo(ability,level);if(!siege(p.kind) || (p.kind==PassiveKind::Barrage && projectile.weapon!=1))continue;projectile.procs.push_back(p);if(p.kind==PassiveKind::FrostBreath && !p.attackMissile.empty())projectile.definition.model=p.attackMissile;if(p.kind==PassiveKind::FreezingBreath && alive(projectile.target,NativeKind::Unit) && passiveTarget(unit,*units_.at(projectile.target),p))lightningWeapon(projectile.definition,p);if(p.kind==PassiveKind::Barrage){auto clock=ambientClocks_.find({unit.handle,p.ability});if(clock!=ambientClocks_.end()){float speed=std::clamp(1+unit.technology.attackSpeed+unit.equipment.attackSpeed+unit.aura.attackSpeed+unit.spellBonus(&UnitBuff::attackBonus)-unit.spellAttackReduction(),.2f,5.f);clock->second.remaining=std::max(1./32,double(projectile.definition.cooldown/speed));}}if(p.kind==PassiveKind::BurningOil || p.kind==PassiveKind::Barrage)lightningWeapon(projectile.definition,p);}
}
void ScriptSession::barrageVolley(const CombatProjectile& main){
    auto proc=std::find_if(main.procs.begin(),main.procs.end(),[](auto& p){return p.kind==PassiveKind::Barrage;});if(proc==main.procs.end() || !alive(main.source,NativeKind::Unit))return;auto from=units_.at(main.source);auto& p=*proc;std::vector<std::pair<float,std::uint32_t>> targets;for(auto& [id,u]:units_)if(id!=main.target && passiveTarget(*from,*u,p) && unitVisibleTo(id,main.owner) && weaponTarget(*from,*u,main.definition,true)){float distance=std::hypot(number(u->x)-number(from->x),number(u->y)-number(from->y));if(distance<=std::min(p.area,main.definition.range)+u->collision)targets.emplace_back(distance,id);}std::sort(targets.begin(),targets.end());unsigned count=1;float allocated=main.damage;for(auto [distance,id]:targets){if(count>=p.maxTargets || (p.secondary>0 && allocated>=p.secondary))break;if(projectiles_.size()>=8192)throw std::runtime_error("Barrage projectile budget exceeded");auto u=units_.at(id);auto shot=main;shot.id=++projectileId_;shot.target=id;shot.damage=main.damage;if(p.secondary>0)shot.damage=std::min(shot.damage,std::max(0.f,p.secondary-allocated));if(shot.damage<=0)continue;allocated+=shot.damage;++count;shot.endpoint={u->x,u->y};shot.endMovement=pathMovement(u->movementType);shot.endHeight=u->displayFlyHeight()+definitions().number(u->type,"UnitWeapons","impactZ",60);shot.distance=std::hypot(number(shot.endpoint.x)-number(shot.start.x),number(shot.endpoint.y)-number(shot.start.y));shot.visited={id};projectiles_.emplace(shot.id,std::move(shot));}
}
void ScriptSession::barragePulse(std::uint32_t id,const PassiveInfo& p,AmbientClock& clock){
    auto u=units_.at(id);auto available=passiveAbilities(*u);if(std::none_of(available.begin(),available.end(),[&](auto entry){return entry.first==p.ability && entry.second==p.level;}))return;if(u->stunned() || u->spinning() || u->ethereal() || u->attackPrevented(true) || !weaponEnabled(*u,1))return;if(u->combat.target && alive(u->combat.target,NativeKind::Unit) && weaponFor(*u,*units_.at(u->combat.target),false)==std::optional<unsigned>{1})return;auto weapon=unitWeapon(*u,1);float nearest=std::min(p.area,weapon.range);std::uint32_t target=0;for(auto candidate:ambientNearby({u->x,u->y},nearest)){if(!alive(candidate,NativeKind::Unit))continue;auto victim=units_.at(candidate);float distance=std::hypot(number(victim->x)-number(u->x),number(victim->y)-number(u->y));if((distance<nearest || (distance==nearest && (!target || candidate<target))) && passiveTarget(*u,*victim,p) && unitVisibleTo(candidate,u->owner) && weaponTarget(*u,*victim,weapon,true)){nearest=distance;target=candidate;}}if(!target)return;float speed=std::clamp(1+u->technology.attackSpeed+u->equipment.attackSpeed+u->aura.attackSpeed+u->spellBonus(&UnitBuff::attackBonus)-u->spellAttackReduction(),.2f,5.f);clock.remaining=std::max(1./32,double(weapon.cooldown/speed));auto death=u->deathRevision,ownership=u->ownerRevision;ScriptContext context;context.attacker=id;unitEvent(target,18,62,context);if(alive(id,NativeKind::Unit) && u->deathRevision==death && u->ownerRevision==ownership && !u->removing && number(u->life)>0)launchAttack(id,target,1);
}
void ScriptSession::siegeImpact(const CombatProjectile& projectile,bool primary){
    plagueTossImpact(projectile);frostBreathImpact(projectile);if(!alive(projectile.source,NativeKind::Unit))return;auto source=units_.at(projectile.source);auto death=source->deathRevision,ownership=source->ownerRevision;auto active=[&]{return alive(projectile.source,NativeKind::Unit) && !source->removing && source->deathRevision==death && source->ownerRevision==ownership;};
    for(auto& p:projectile.procs){if(!active())return;if(p.kind==PassiveKind::BurningOil){if(siegeFires_.size()>=4096)throw std::runtime_error("Ground siege fire budget exceeded");SiegeFire fire;fire.definition=p;fire.source=projectile.source;fire.owner=projectile.owner;fire.point=projectile.endpoint;fire.nextPulse=p.period;if(p.effectBuff){SpellInfo art;art.ability=p.effectBuff;fire.visuals=spellVisual(art,"EffectArt",0,fire.point,false);}siegeFires_.emplace(++spellTicket_,std::move(fire));continue;}
        if(p.kind==PassiveKind::LiquidFire){if(!primary || !alive(projectile.target,NativeKind::Unit))continue;auto target=units_.at(projectile.target);if(!target->building || !passiveTarget(*source,*target,p))continue;double period=0;if(auto old=target->buffs.find(p.buff);old!=target->buffs.end() && old->second.kind==BuffKind::LiquidFire)period=old->second.period;SpellInfo spell;spell.ability=p.ability;spell.level=p.level;spell.buff=p.buff;spell.duration=p.duration;spell.heroDuration=p.heroDuration;applyBuff(projectile.target,projectile.source,spell,BuffKind::LiquidFire,true);if(auto buff=target->buffs.find(p.buff);buff!=target->buffs.end() && buff->second.kind==BuffKind::LiquidFire){buff->second.sourceOwner=projectile.owner;buff->second.damage=p.amount;buff->second.moveReduction=p.secondary;buff->second.attackReduction=p.bonus;buff->second.preventsRepair=!p.repairAllowed;buff->second.period=period;buff->second.dispellable=false;}continue;}
        if(p.kind!=PassiveKind::FlakCannon && p.kind!=PassiveKind::Fragmentation)continue;float radius=*std::max_element(p.splashRadii.begin(),p.splashRadii.end());std::vector<std::uint32_t> victims;for(auto& [id,u]:units_)if((p.kind!=PassiveKind::FlakCannon || id!=projectile.target) && passiveTarget(*source,*u,p) && std::hypot(number(u->x)-number(projectile.endpoint.x),number(u->y)-number(projectile.endpoint.y))<=radius+u->collision)victims.push_back(id);
        for(auto id:victims){if(!active())return;if(!alive(id,NativeKind::Unit))continue;auto u=units_.at(id);if(!passiveTarget(*source,*u,p))continue;if(p.kind==PassiveKind::Fragmentation){if((!u->roots || !u->roots->uprooted) && u->technology.defenseType<0)throw std::runtime_error("Unknown source defense type: "+definitions().field(u->type,"UnitBalance","defType","normal"));auto armor=defenseType(*u);if(armor!=1 && armor!=7)continue;}float distance=std::hypot(number(u->x)-number(projectile.endpoint.x),number(u->y)-number(projectile.endpoint.y)),damage=0;for(unsigned zone=0;zone<3;++zone)if(distance<=p.splashRadii[zone]+u->collision){damage=p.splashDamage[zone];break;}if(damage<=0)continue;auto targetDeath=u->deathRevision;damageUnit(projectile.source,id,damage,2,4,false,true);if(active() && alive(id,NativeKind::Unit) && u->deathRevision==targetDeath && !u->removing && number(u->life)>0){SpellInfo art;art.ability=p.ability;spellVisual(art,"TargetArt",id,{u->x,u->y});}}
    }
}
void ScriptSession::siegeFiresTick(double delta){
    if(siegeFires_.empty())return;bool due=std::any_of(siegeFires_.begin(),siegeFires_.end(),[&](auto& entry){auto& fire=entry.second;return fire.nextPulse<=fire.elapsed+delta+1e-7 && fire.nextPulse<=fire.definition.duration+1e-7;});if(due){ambientGrid_.clear();for(auto& [id,u]:units_)if(!u->removing && !u->hidden() && number(u->life)>0){auto cell=[](float value){return int(std::clamp(std::floor(double(value)/512),double(INT_MIN),double(INT_MAX)));};auto key=(std::uint64_t(std::uint32_t(cell(number(u->x))))<<32)|std::uint32_t(cell(number(u->y)));ambientGrid_[key].push_back(id);}}
    std::vector<std::uint64_t> actors;for(auto& [id,fire]:siegeFires_)actors.push_back(id);for(auto id:actors){auto found=siegeFires_.find(id);if(found==siegeFires_.end())continue;auto fire=std::move(found->second);siegeFires_.erase(found);auto& p=fire.definition;fire.elapsed+=delta;
        while(fire.nextPulse<=fire.elapsed+1e-7 && fire.nextPulse<=p.duration+1e-7){bool full=fire.nextPulse<=p.heroDuration+1e-7;float amount=full?p.amount:p.innerDamage;UnitState source;source.handle=fire.source;source.owner=fire.owner;std::vector<std::uint32_t> victims;for(auto target:ambientNearby(fire.point,p.area)){if(!alive(target,NativeKind::Unit))continue;auto u=units_.at(target);if(passiveTarget(source,*u,p) && std::hypot(number(u->x)-number(fire.point.x),number(u->y)-number(fire.point.y))<=p.area+u->collision)victims.push_back(target);}for(auto target:victims){if(!alive(target,NativeKind::Unit))continue;auto u=units_.at(target);if(!passiveTarget(source,*u,p))continue;auto caster=alive(fire.source,NativeKind::Unit) && !units_.at(fire.source)->removing && units_.at(fire.source)->owner==fire.owner?fire.source:0;damageUnit(caster,target,amount*(u->building?p.magicFactor:1),0,8,false,false,nullptr,false,true,fire.owner);}fire.nextPulse+=full?p.period:p.evasion;if(full && fire.nextPulse>p.heroDuration+1e-7)fire.nextPulse=p.heroDuration+p.evasion;}
        if(fire.elapsed>=p.duration){for(auto effect:fire.visuals)destroyEffect(effect);}else siegeFires_.emplace(id,std::move(fire));
    }
}
